def icon(name):
    """A decorative Regular icon; saved bookmarks also have an official Fill glyph."""
    key = _NAMES[name]
    body = _PATHS[key]
    if name == "bookmark":
        body = (f'<g class="icon-regular">{body}</g>'
                f'<g class="icon-fill">{_BOOKMARK_FILL}</g>')
    return (f'<svg class="icon" viewBox="0 0 256 256" fill="currentColor" '
            f'data-icon-family="phosphor" data-icon="{key}" '
            f'aria-hidden="true" focusable="false">{body}</svg>')
